package com.neocoffee.smsgateway;
import android.app.*;import android.content.*;import android.os.*;import android.telephony.SmsManager;import android.telephony.SubscriptionManager;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.text.DateFormat;import java.util.Date;import java.util.concurrent.*;
public class GatewayService extends Service {
 static final String CHANNEL="neo_sms_gateway";private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable poll=new Runnable(){public void run(){executor.execute(()->{try{fetchAndSend();}catch(Exception e){save("تعذر الاتصال: "+e.getMessage());}finally{handler.postDelayed(poll,15000);}});}};
 @Override public void onCreate(){super.onCreate();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel(CHANNEL,"Neo SMS Gateway",NotificationManager.IMPORTANCE_LOW));Notification n=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_notify_chat).setContentTitle("Neo Coffee SMS").setContentText("بوابة أكواد التحقق تعمل").setOngoing(true).build();startForeground(71,n);}
 @Override public int onStartCommand(Intent i,int flags,int id){handler.removeCallbacks(poll);handler.post(poll);return START_STICKY;}
 private void fetchAndSend()throws Exception{SharedPreferences p=getSharedPreferences("gateway",MODE_PRIVATE);String base=p.getString("url","");String token=p.getString("token","");if(base.isEmpty()||token.isEmpty())throw new Exception("الإعدادات غير مكتملة");HttpURLConnection c=open(base+"/api/sms-gateway/jobs",token,"GET");int code=c.getResponseCode();String body=read(code<400?c.getInputStream():c.getErrorStream());if(code!=200)throw new Exception("الخادم رد "+code);JSONArray jobs=new JSONObject(body).getJSONArray("jobs");if(jobs.length()==0){save("متصل — لا توجد رسائل منتظرة");return;}for(int x=0;x<jobs.length();x++)send(jobs.getJSONObject(x),base,token);}
 private void send(JSONObject job,String base,String token)throws Exception{int id=job.getInt("id");String phone=job.getString("phone"),message=job.getString("message");int subId=getSharedPreferences("gateway",MODE_PRIVATE).getInt("sub_id",SubscriptionManager.getDefaultSmsSubscriptionId());String sim="SIM subscription "+subId;Intent result=new Intent(this,SmsResultReceiver.class).putExtra("id",id).putExtra("base",base).putExtra("token",token).putExtra("phone",phone).putExtra("sim",sim);PendingIntent pi=PendingIntent.getBroadcast(this,id,result,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);SmsManager manager;if(Build.VERSION.SDK_INT>=31)manager=getSystemService(SmsManager.class).createForSubscriptionId(subId);else manager=SmsManager.getSmsManagerForSubscriptionId(subId);manager.sendTextMessage(phone,null,message,pi,null);save("جاري إرسال كود إلى "+phone+" من الخط المختار");}
 static HttpURLConnection open(String url,String token,String method)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json");c.setConnectTimeout(10000);c.setReadTimeout(10000);return c;}static String read(InputStream in)throws Exception{if(in==null)return "";try(in){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[]buf=new byte[2048];for(int n;(n=in.read(buf))!=-1;)b.write(buf,0,n);return b.toString(StandardCharsets.UTF_8.name());}}
 private void save(String text){getSharedPreferences("gateway",MODE_PRIVATE).edit().putString("last",DateFormat.getDateTimeInstance().format(new Date())+" — "+text).apply();}@Override public void onDestroy(){handler.removeCallbacks(poll);executor.shutdownNow();getSharedPreferences("gateway",MODE_PRIVATE).edit().putBoolean("running",false).apply();super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
